import { Component } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-ejercicio15',
  templateUrl: './ejercicio15.component.html',
  styleUrls: ['./ejercicio15.component.css']
})
export class Ejercicio15Component {

  public productoBuscado: string = '';
  public numeroDeCompras: number = 0;
  constructor(private misComprasService: MisComprasService) { }

  buscarProducto(): void {
    if (this.productoBuscado.trim() === '') {
      this.numeroDeCompras = 0;
      return;
    }

    this.misComprasService.obtenerNumeroComprasProducto(this.productoBuscado).subscribe(
      (res) => {
        this.numeroDeCompras = res.totalCompras;
      },
      error => {
        console.error('Error al obtener el número de compras', error);
        this.numeroDeCompras = 0;
      }
    );
  }

}
<div>
  <h2>Buscador de Compras</h2>
  <input [(ngModel)]="productoBuscado" placeholder="Introduce el nombre del producto" />
  <button (click)="buscarProducto()">Buscar</button>

  <div *ngIf="numeroDeCompras > 0">
    <p>El producto "{{ productoBuscado }}" se ha comprado en {{ numeroDeCompras }} compras.</p>
  </div>
  <div *ngIf="numeroDeCompras === 0 && productoBuscado.trim() !== ''">
    <p>No se han encontrado compras para el producto "{{ productoBuscado }}".</p>
  </div>
</div>
